/**
 * AQB Core Types
 *
 * These types define the interfaces for the Agentic Quality Benchmark.
 * Tool adapters, corpus samples, findings, and evaluation results
 * all conform to these schemas.
 */

// ─── Domains ────────────────────────────────────────────────────────────────

export type Domain =
  | 'security'
  | 'defects'
  | 'test-generation'
  | 'coverage-analysis'
  | 'requirements'
  | 'contracts'
  | 'quality'
  | 'accessibility'
  | 'performance'
  | 'chaos-resilience'
  | 'code-intelligence'
  | 'enterprise-integration'
  | 'flaky-tests'
  | 'visual-regression';

export type Severity = 'critical' | 'high' | 'medium' | 'low' | 'info';

export type Difficulty = 1 | 2 | 3 | 4 | 5;

export type Language = 'typescript' | 'javascript' | 'python' | 'java' | 'go' | 'rust' | 'csharp' | 'other';

export type SourcingMethod =
  | 'real_cve'
  | 'historical_bugfix'
  | 'mutation_seeded'
  | 'synthetic'
  | 'adversarial_negative';

// ─── Corpus ─────────────────────────────────────────────────────────────────

export interface CorpusSample {
  id: string;
  domain: Domain;
  category: string;
  language: Language;
  difficulty: Difficulty;
  files: SampleFile[];
  ground_truth: GroundTruth;
  metadata: SampleMetadata;
}

export interface SampleFile {
  path: string;
  content: string;
}

export interface GroundTruth {
  issues: GroundTruthIssue[];
  false_positives: FalsePositiveMarker[];
}

export interface GroundTruthIssue {
  type: string;            // CWE-89, null-deref, etc.
  severity: Severity;
  location: Location;
  description: string;
  fix_available: boolean;
  fix_file?: string;       // Path to patch file
}

export interface FalsePositiveMarker {
  location: Location;
  reason: string;           // Why this is NOT an issue
}

export interface Location {
  file: string;
  line_start: number;
  line_end: number;
  column_start?: number;
  column_end?: number;
}

export interface SampleMetadata {
  source: string;           // CVE ID, commit hash, or "synthetic"
  sourcing_method: SourcingMethod;
  human_verified: boolean;
  verification_date: string;
  verified_by?: string[];
}

// ─── Findings ───────────────────────────────────────────────────────────────

export interface Finding {
  id: string;
  domain: Domain;
  category: string;
  severity: Severity;
  confidence: number;       // 0-1
  location: Location;
  description: string;
  suggestion?: string;
  fix?: string;
  metadata?: Record<string, unknown>;
}

// ─── Adapter Interface ──────────────────────────────────────────────────────

export interface AQBToolAdapter {
  name: string;
  version: string;

  /** Run the tool against a single corpus sample */
  analyze(sample: CorpusSample): Promise<Finding[]>;

  /** Optional setup before evaluation run */
  setup?(): Promise<void>;

  /** Optional teardown after evaluation run */
  teardown?(): Promise<void>;
}

// ─── Matching ───────────────────────────────────────────────────────────────

export type MatchType = 'full' | 'partial' | 'none';

export interface MatchedFinding {
  finding: Finding;
  ground_truth: GroundTruthIssue;
  match_type: MatchType;
  match_score: number;       // 0-1
}

export interface UnmatchedFinding {
  finding: Finding;
  reason: 'no_ground_truth' | 'wrong_location' | 'wrong_type' | 'fabrication';
}

export interface MissedIssue {
  ground_truth: GroundTruthIssue;
  sample_id: string;
}

// ─── Results ────────────────────────────────────────────────────────────────

export interface AQBResult {
  tool: string;
  version: string;
  run_id: string;
  timestamp: string;
  corpus_version: string;

  findings: Finding[];

  matches: {
    true_positives: MatchedFinding[];
    false_positives: UnmatchedFinding[];
    false_negatives: MissedIssue[];
    true_negatives: number;
  };

  metrics: AQBMetrics;
  domain_metrics: Record<Domain, DomainMetrics>;
  difficulty_metrics: Record<Difficulty, { recall: number }>;
  language_metrics: Record<Language, { precision: number; recall: number }>;
}

export interface AQBMetrics {
  precision: number;
  recall: number;
  f1: number;
  false_positive_rate: number;
  fabrication_rate: number;             // Findings on clean code / total findings
  severity_weighted_recall: number;     // Critical weighted 3x
  mean_time_to_detect_ms: number;
  total_latency_ms: number;
  token_cost_usd: number;
  findings_per_dollar: number;
}

export interface DomainMetrics {
  precision: number;
  recall: number;
  f1: number;
  samples_evaluated: number;
  avg_latency_ms: number;
}

// ─── Agentic Metrics ────────────────────────────────────────────────────────

export interface AgenticMetrics {
  learning_transfer: {
    cold_start_recall: number;
    warm_start_recall: number;
    delta_recall: number;
  };
  multi_agent: {
    single_agent_recall: number;
    swarm_recall: number;
    unique_findings_per_agent: number;
    coordination_overhead_ms: number;
  };
  explanation_quality: {
    llm_judge_score: number;         // 1-5
    human_validation_score?: number; // 1-5 (on sample)
    inter_rater_kappa?: number;
  };
  fix_quality: {
    fixes_attempted: number;
    fixes_compiled: number;
    fixes_passed_tests: number;
    fix_success_rate: number;
  };
  severity_calibration: {
    spearman_rho: number;
    kendall_tau: number;
  };
  cost_efficiency: {
    total_tokens: number;
    total_cost_usd: number;
    findings_per_dollar: number;
    cost_per_true_positive: number;
  };
  temporal_decay?: {
    recall_t0: number;
    recall_t3m: number;
    recall_t6m: number;
    decay_rate: number;
  };
}

// ─── Scorecard ──────────────────────────────────────────────────────────────

export interface Scorecard {
  tool: string;
  version: string;
  corpus_version: string;
  timestamp: string;
  overall: AQBMetrics;
  domains: Record<Domain, DomainMetrics>;
  difficulty: Record<Difficulty, { recall: number }>;
  languages: Record<Language, { precision: number; recall: number }>;
  agentic?: AgenticMetrics;
}

/**
 * AQB Harness - Agentic Quality Benchmark
 *
 * Evaluation harness for measuring QE agent effectiveness.
 */

export * from './types.js';
export { matchFindings } from './matcher.js';
export type { MatcherConfig } from './matcher.js';
export { computeMetrics, computeDomainMetrics, computeDifficultyMetrics } from './metrics.js';
export type { MetricsInput } from './metrics.js';

/**
 * Finding-to-Ground-Truth Matcher
 *
 * Implements fuzzy matching between tool findings and corpus ground truth.
 * Uses location proximity + issue type compatibility.
 */

import type {
  Finding,
  GroundTruthIssue,
  MatchedFinding,
  UnmatchedFinding,
  MissedIssue,
  MatchType,
  CorpusSample,
} from './types.js';

/** Configuration for matching behavior */
export interface MatcherConfig {
  /** Maximum line distance for single-line issues (default: 5) */
  lineProximity: number;
  /** Minimum line range overlap for multi-line issues (default: 0.5) */
  overlapThreshold: number;
  /** Partial match score (default: 0.5) */
  partialMatchWeight: number;
  /** Category compatibility map (e.g., CWE-89 matches sql-injection) */
  categoryAliases: Record<string, string[]>;
}

const DEFAULT_CONFIG: MatcherConfig = {
  lineProximity: 5,
  overlapThreshold: 0.5,
  partialMatchWeight: 0.5,
  categoryAliases: {
    'CWE-89': ['sql-injection', 'sqli'],
    'CWE-79': ['xss', 'cross-site-scripting'],
    'CWE-78': ['command-injection', 'os-injection'],
    'CWE-22': ['path-traversal', 'directory-traversal'],
    'CWE-798': ['hardcoded-secrets', 'hardcoded-credentials'],
    'CWE-327': ['crypto-weakness', 'weak-cryptography'],
    'CWE-918': ['ssrf', 'server-side-request-forgery'],
  },
};

/**
 * Match findings against ground truth for a corpus sample.
 */
export function matchFindings(
  findings: Finding[],
  sample: CorpusSample,
  config: Partial<MatcherConfig> = {},
): {
  true_positives: MatchedFinding[];
  false_positives: UnmatchedFinding[];
  false_negatives: MissedIssue[];
} {
  const cfg = { ...DEFAULT_CONFIG, ...config };
  const groundTruth = sample.ground_truth.issues;
  const fpMarkers = sample.ground_truth.false_positives;

  const true_positives: MatchedFinding[] = [];
  const false_positives: UnmatchedFinding[] = [];
  const matched_gt_indices = new Set<number>();

  // Match each finding to the best ground truth issue
  for (const finding of findings) {
    let bestMatch: { gt: GroundTruthIssue; idx: number; score: number; type: MatchType } | null = null;

    for (let i = 0; i < groundTruth.length; i++) {
      if (matched_gt_indices.has(i)) continue;

      const gt = groundTruth[i];
      const match = computeMatch(finding, gt, cfg);

      if (match && (!bestMatch || match.score > bestMatch.score)) {
        bestMatch = { gt, idx: i, ...match };
      }
    }

    if (bestMatch) {
      matched_gt_indices.add(bestMatch.idx);
      true_positives.push({
        finding,
        ground_truth: bestMatch.gt,
        match_type: bestMatch.type,
        match_score: bestMatch.score,
      });
    } else {
      // Check if this is a known false positive marker
      const isFabricatedOnClean = sample.metadata.sourcing_method === 'adversarial_negative';
      false_positives.push({
        finding,
        reason: isFabricatedOnClean ? 'fabrication' : 'no_ground_truth',
      });
    }
  }

  // Remaining unmatched ground truth = false negatives
  const false_negatives: MissedIssue[] = groundTruth
    .filter((_, i) => !matched_gt_indices.has(i))
    .map(gt => ({ ground_truth: gt, sample_id: sample.id }));

  return { true_positives, false_positives, false_negatives };
}

/**
 * Compute match between a finding and a ground truth issue.
 */
function computeMatch(
  finding: Finding,
  gt: GroundTruthIssue,
  cfg: MatcherConfig,
): { score: number; type: MatchType } | null {
  // Step 1: File must match
  if (!filesMatch(finding.location.file, gt.location.file)) {
    return null;
  }

  // Step 2: Location proximity
  const locationScore = computeLocationScore(finding.location, gt.location, cfg);
  if (locationScore === 0) {
    return null;
  }

  // Step 3: Domain/category compatibility
  const categoryScore = computeCategoryScore(finding, gt, cfg);

  if (categoryScore >= 1.0) {
    // Full match: location + category both match
    return { score: locationScore * categoryScore, type: 'full' };
  } else if (categoryScore > 0) {
    // Partial match: location matches but category is only compatible
    return {
      score: locationScore * categoryScore * cfg.partialMatchWeight,
      type: 'partial',
    };
  }

  return null;
}

function filesMatch(a: string, b: string): boolean {
  // Normalize paths for comparison
  const normalize = (p: string) => p.replace(/^\.\//, '').replace(/\\/g, '/');
  return normalize(a) === normalize(b);
}

function computeLocationScore(
  finding: { line_start: number; line_end: number },
  gt: { line_start: number; line_end: number },
  cfg: MatcherConfig,
): number {
  const fStart = finding.line_start;
  const fEnd = finding.line_end;
  const gStart = gt.line_start;
  const gEnd = gt.line_end;

  // Single-line issues: use proximity
  if (gStart === gEnd) {
    const distance = Math.min(Math.abs(fStart - gStart), Math.abs(fEnd - gStart));
    if (distance <= cfg.lineProximity) {
      return 1 - (distance / (cfg.lineProximity + 1));
    }
    return 0;
  }

  // Multi-line issues: use overlap
  const overlapStart = Math.max(fStart, gStart);
  const overlapEnd = Math.min(fEnd, gEnd);
  const overlap = Math.max(0, overlapEnd - overlapStart + 1);
  const gtRange = gEnd - gStart + 1;
  const overlapRatio = overlap / gtRange;

  return overlapRatio >= cfg.overlapThreshold ? overlapRatio : 0;
}

function computeCategoryScore(
  finding: Finding,
  gt: GroundTruthIssue,
  cfg: MatcherConfig,
): number {
  // Exact match
  if (finding.category === gt.type) return 1.0;

  // Check aliases
  const findingAliases = cfg.categoryAliases[finding.category] || [];
  const gtAliases = cfg.categoryAliases[gt.type] || [];

  if (findingAliases.includes(gt.type) || gtAliases.includes(finding.category)) {
    return 1.0;
  }

  // Check if they share any alias group
  for (const [, aliases] of Object.entries(cfg.categoryAliases)) {
    const findingInGroup = aliases.includes(finding.category) || finding.category in cfg.categoryAliases;
    const gtInGroup = aliases.includes(gt.type) || gt.type in cfg.categoryAliases;
    if (findingInGroup && gtInGroup) {
      return 0.7; // Same family but not exact
    }
  }

  // Domain match but different category (e.g., both security but different vuln type)
  if (finding.domain === domainFromType(gt.type)) {
    return 0.3;
  }

  return 0;
}

function domainFromType(type: string): string {
  if (type.startsWith('CWE-')) return 'security';
  if (['null-deref', 'race-condition', 'off-by-one', 'resource-leak', 'state-corruption', 'type-confusion'].includes(type)) return 'defects';
  return 'unknown';
}

/**
 * AQB Metrics Calculator
 *
 * Computes precision, recall, F1, fabrication rate, and other metrics
 * from matched findings.
 */

import type {
  AQBMetrics,
  DomainMetrics,
  Domain,
  Difficulty,
  Language,
  MatchedFinding,
  UnmatchedFinding,
  MissedIssue,
} from './types.js';

export interface MetricsInput {
  true_positives: MatchedFinding[];
  false_positives: UnmatchedFinding[];
  false_negatives: MissedIssue[];
  true_negatives: number;
  total_latency_ms: number;
  token_cost_usd: number;
}

/**
 * Compute aggregate AQB metrics from matching results.
 */
export function computeMetrics(input: MetricsInput): AQBMetrics {
  const tp = input.true_positives.length;
  const fp = input.false_positives.length;
  const fn = input.false_negatives.length;
  const tn = input.true_negatives;

  const precision = tp + fp > 0 ? tp / (tp + fp) : 0;
  const recall = tp + fn > 0 ? tp / (tp + fn) : 0;
  const f1 = precision + recall > 0 ? (2 * precision * recall) / (precision + recall) : 0;
  const fpr = fp + tn > 0 ? fp / (fp + tn) : 0;

  // Fabrication rate: findings on adversarial negatives
  const fabrications = input.false_positives.filter(f => f.reason === 'fabrication').length;
  const totalFindings = tp + fp;
  const fabrication_rate = totalFindings > 0 ? fabrications / totalFindings : 0;

  // Severity-weighted recall: critical=3x, high=2x, medium=1x, low=0.5x
  const severityWeights: Record<string, number> = {
    critical: 3,
    high: 2,
    medium: 1,
    low: 0.5,
    info: 0.25,
  };

  let weightedTP = 0;
  let weightedTotal = 0;

  for (const match of input.true_positives) {
    const w = severityWeights[match.ground_truth.severity] || 1;
    weightedTP += w * match.match_score;
    weightedTotal += w;
  }
  for (const miss of input.false_negatives) {
    const w = severityWeights[miss.ground_truth.severity] || 1;
    weightedTotal += w;
  }

  const severity_weighted_recall = weightedTotal > 0 ? weightedTP / weightedTotal : 0;

  // Cost efficiency
  const findings_per_dollar = input.token_cost_usd > 0 ? tp / input.token_cost_usd : Infinity;

  // Mean time to detect (average latency per true positive)
  const mean_time_to_detect_ms = tp > 0 ? input.total_latency_ms / tp : 0;

  return {
    precision,
    recall,
    f1,
    false_positive_rate: fpr,
    fabrication_rate,
    severity_weighted_recall,
    mean_time_to_detect_ms,
    total_latency_ms: input.total_latency_ms,
    token_cost_usd: input.token_cost_usd,
    findings_per_dollar,
  };
}

/**
 * Compute per-domain metrics breakdown.
 */
export function computeDomainMetrics(
  true_positives: MatchedFinding[],
  false_positives: UnmatchedFinding[],
  false_negatives: MissedIssue[],
  domainLatencies: Record<Domain, number[]>,
  domainSampleCounts: Record<Domain, number>,
): Record<Domain, DomainMetrics> {
  const domains = new Set<Domain>();

  for (const tp of true_positives) domains.add(tp.finding.domain);
  for (const fp of false_positives) domains.add(fp.finding.domain);

  const result: Partial<Record<Domain, DomainMetrics>> = {};

  for (const domain of domains) {
    const domainTP = true_positives.filter(tp => tp.finding.domain === domain);
    const domainFP = false_positives.filter(fp => fp.finding.domain === domain);
    const domainFN = false_negatives.filter(fn => fn.ground_truth.type.startsWith('CWE-') ? domain === 'security' : true);

    const tp = domainTP.length;
    const fp = domainFP.length;
    const fn = domainFN.length;

    const precision = tp + fp > 0 ? tp / (tp + fp) : 0;
    const recall = tp + fn > 0 ? tp / (tp + fn) : 0;
    const f1 = precision + recall > 0 ? (2 * precision * recall) / (precision + recall) : 0;

    const latencies = domainLatencies[domain] || [];
    const avg_latency_ms = latencies.length > 0
      ? latencies.reduce((a, b) => a + b, 0) / latencies.length
      : 0;

    result[domain] = {
      precision,
      recall,
      f1,
      samples_evaluated: domainSampleCounts[domain] || 0,
      avg_latency_ms,
    };
  }

  return result as Record<Domain, DomainMetrics>;
}

/**
 * Compute per-difficulty recall breakdown.
 */
export function computeDifficultyMetrics(
  true_positives: MatchedFinding[],
  false_negatives: MissedIssue[],
  sampleDifficulties: Map<string, Difficulty>,
): Record<Difficulty, { recall: number }> {
  const result: Record<number, { tp: number; total: number }> = {
    1: { tp: 0, total: 0 },
    2: { tp: 0, total: 0 },
    3: { tp: 0, total: 0 },
    4: { tp: 0, total: 0 },
    5: { tp: 0, total: 0 },
  };

  // Count by difficulty (approximate - using sample difficulty for TPs)
  for (const tp of true_positives) {
    const difficulty = sampleDifficulties.get(tp.finding.id) || 3;
    result[difficulty].tp++;
    result[difficulty].total++;
  }

  for (const fn of false_negatives) {
    const difficulty = sampleDifficulties.get(fn.sample_id) || 3;
    result[difficulty].total++;
  }

  return {
    1: { recall: result[1].total > 0 ? result[1].tp / result[1].total : 0 },
    2: { recall: result[2].total > 0 ? result[2].tp / result[2].total : 0 },
    3: { recall: result[3].total > 0 ? result[3].tp / result[3].total : 0 },
    4: { recall: result[4].total > 0 ? result[4].tp / result[4].total : 0 },
    5: { recall: result[5].total > 0 ? result[5].tp / result[5].total : 0 },
  } as Record<Difficulty, { recall: number }>;
}

/**
 * AQB Tool Adapter Interface
 *
 * Implement this interface to evaluate any QE tool against the AQB corpus.
 *
 * @example
 * ```typescript
 * import { AQBToolAdapter, CorpusSample, Finding } from '@aqb/harness';
 *
 * export class SemgrepAdapter implements AQBToolAdapter {
 *   name = 'semgrep';
 *   version = '1.x.x';
 *
 *   async analyze(sample: CorpusSample): Promise<Finding[]> {
 *     // Write sample files to temp directory
 *     // Run semgrep against them
 *     // Parse output into Finding[] format
 *     // Return findings
 *   }
 * }
 * ```
 */

export type { AQBToolAdapter, CorpusSample, Finding } from '../types.js';
